parameters.jsCode:
// Explode each relevant AI result into one row per catalog item, mapped to the REAL
// catalog_lines columns, and decide DETERMINISTICALLY (no AI) whether each item is a
// new line or an update to an existing one. v15: document type drives the catalog
// (invoice -> other, release -> main; orders never enter), digital releases are
// dropped, the label map is table-driven, and non-standard features are surfaced in
// the title. v19: the catalog EAN is normalised to 13 digits (a 12-digit UPC gets a
// leading zero); Hermes still receives the de-zeroed barcode.
// v20: rows with no ean+title+artist are dropped, and the INSERT runs one row at a
// time so a single duplicate barcode can no longer discard the whole batch.
// v21: mail from a BLOCKED sender (I-DI Offer) never enters the catalog, matched even
// when the client forwards it in.
// v22: a sub-label printed with its distributor ("Mute/[PIAS]") resolves to the sender's
// canonical label, and supplier_code falls back to the sender so it is never null.
// v23: internal Nika mail ABOUT STOCK (a colleague's stock list, sent straight to Mare or
// forwarded in) never enters the catalog.
// v25: a supplier invoice also bills FEE / CHARGE lines (Warner's LINEFEE "Charge per
// shipped order line", UNITFEE "Charge per shipped unit", freight, handling). They are
// accounting lines, never products, and can NEVER enter the catalog.
// v25: the LABEL and the DOCUMENT TYPE are properties of the whole MESSAGE, not of the
// chunk the model happened to read — they are resolved once per message_id and shared by
// every chunk, so a chunk that never saw the letterhead cannot lose them.

function toCatalogCode(ean) {
  if (ean === null || ean === undefined) return null;
  const s = String(ean).replace(/\D/g, '');
  if (!s) return null;
  const trimmed = s.slice(0, -1).replace(/^0+/, '');
  return trimmed || null;
}

// Catalog EAN is ALWAYS 13 digits: a 12-digit UPC gets one leading zero
// (075678581519 -> 0075678581519); shorter values are left-padded to 13, 13+ kept as-is.
// Hermes still receives the de-zeroed barcode (that strip lives in the send workflow).
function toEan13(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).replace(/\D/g, '');
  if (!s) return null;
  return s.length < 13 ? s.padStart(13, '0') : s;
}

// Never trust the model: neither artist nor title may start OR end with "THE".
function dropThe(s) {
  if (typeof s !== 'string') return s;
  const orig = s;
  let t = s;
  while (t[0] === ' ') t = t.slice(1);
  if (t.slice(0, 4).toUpperCase() === 'THE ') { t = t.slice(4); while (t[0] === ' ') t = t.slice(1); }
  t = t.replace(/[\s,]+THE\s*$/i, '');
  while (t.length && t[t.length - 1] === ' ') t = t.slice(0, -1);
  return t === '' ? orig : t;
}

const VARIANT_RE = /\b(VINYL|LP|CD|MC|DIGI|DIGIPAK|DIGIPACK|LTD|LIMITED|EXCLUSIVE|INDIE|RSD|SIGNED|PICTURE|DISC|DIE-CUT|GATEFOLD|T-SHIRT|PATCH|BOXSET|BOX|DELUXE|EDITION|REISSUE|BLACK|WHITE|RED|GREEN|BLUE|YELLOW|GOLD|SILVER|CLEAR|ORANGE|PURPLE|PINK|GREY|GRAY|MARBLE|SPLATTER|GLITTER|TRANSPARENT|INKSPOT|GLOW|SLUDGE|OPAQUE|CRYSTAL|SOFTPAK|JEWEL|AMARAY|LIGHT)\b/;
function cleanTitle(s) {
  if (typeof s !== 'string') return { title: s, removed: [] };
  const removed = [];
  let t = s.replace(/\s*[\(\[]([^()\[\]]*)[\)\]]/g, function (m, inner) {
    if (VARIANT_RE.test(inner.toUpperCase())) { removed.push(inner.trim()); return ''; }
    return m;
  });
  t = t.replace(/\s+[-–]\s+([^-–]+)$/, function (m, seg) {
    const words = seg.trim().toUpperCase().split(/[\s,\/&+]+/).filter(Boolean);
    if (words.length && words.every(function (w) { return VARIANT_RE.test(w) || /^[0-9]+$/.test(w); })) { removed.push(seg.trim()); return ''; }
    return m;
  });
  t = t.replace(/\s{2,}/g, ' ').replace(/[\s,;:\-–]+$/, '').trim();
  return { title: t, removed: removed };
}
function up(s) { return typeof s === 'string' ? s.toUpperCase() : s; }

// Non-standard features from the product info are surfaced in the TITLE as "(FEATURE)"
// tokens, CAPS, in a fixed order: weight -> colour -> exclusive/special -> limited.
// Standard defaults (black vinyl, 140g, all retail) are never shown. The model supplies
// the raw non-standard features; this orders/formats them so the output is consistent
// no matter how the model lists them. No features -> the clean title as before.
const COLOUR_WORD = /^(RED|WHITE|BLUE|GREEN|YELLOW|GOLD|SILVER|CLEAR|ORANGE|PURPLE|PINK|GREY|GRAY|BROWN|CREAM|AMBER|TURQUOISE|MAGENTA|CRYSTAL|BONE|NATURAL|SMOKE|MARBLE|SPLATTER|GALAXY|GLITTER|COKE BOTTLE|SEA BLUE|BABY BLUE|ECORECORD)( VINYL)?$/;
function isStandardFeature(f) {
  return /^BLACK( VINYL)?$/.test(f) || /^140\s*G/.test(f) || /^(ALL RETAIL|RETAIL|STANDARD|REGULAR|VINYL|ALBUM|12"|1X ?LP|1 X 140G)$/.test(f);
}
function featureBucket(f) {
  if (/\d+\s*G(?:RAMS?)?\b/.test(f)) return 0;                                   // 180G
  if (/VINYL$/.test(f) || COLOUR_WORD.test(f) || /PICTURE DISC|GATEFOLD/.test(f)) return 1; // RED VINYL
  if (/\bLIMIT|\bLTD\b|\bNUMBERED\b/.test(f)) return 3;                          // LIMITED / LTD
  return 2;                                                                      // EXCLUSIVE / BLACK FRIDAY / RSD / SIGNED ...
}
function formatFeatures(features) {
  if (!Array.isArray(features)) return '';
  const seen = {};
  const buckets = [[], [], [], []];
  for (const raw of features) {
    if (typeof raw !== 'string') continue;
    const f = raw.trim().toUpperCase().replace(/^[\(\[]+/, '').replace(/[\)\]]+$/, '').trim();
    if (!f || isStandardFeature(f) || seen[f]) continue;
    seen[f] = true;
    buckets[featureBucket(f)].push(f);
  }
  const ordered = buckets[0].concat(buckets[1], buckets[2], buckets[3]);
  return ordered.map(function (f) { return ' (' + f + ')'; }).join('');
}

function labelKey(s) { return typeof s === 'string' ? s.toUpperCase().replace(/[^A-Z0-9]/g, '') : ''; }

// Supplier code (Hermes) is by LABEL. The catalog (main/other) is NOT decided here any
// more — document type decides it (see below). Codes not yet known are blank.
// Supplier code (Hermes) comes from the Senders table (built below as supplierMap), so the
// client maintains it (I-Di 41, Matrix 54, Pias 1009, Warner 149, Elektra 150...). A blank
// cell means blank. An UNMAPPED label defaults label-aware: a Warner-family name -> 149,
// anything else -> blank (so a new non-Warner label is never wrongly stamped 149).
function supplierLookup(label) {
  const k = labelKey(label);
  // '' means the client knows this label and deliberately left the code blank.
  if (Object.prototype.hasOwnProperty.call(supplierMap, k)) return supplierMap[k] || null;
  return undefined; // not in the table at all
}
// supplier_code answers "who do we BUY from", which is the company that mailed us — not
// the imprint printed on the sleeve. So an unmapped item label falls back to the SENDER's
// code before the Warner-family heuristic. Without this a [PIAS] sub-label such as
// "Mute/[PIAS]" produced supplier_code null, and null blocks the Hermes send.
function supplierCodeFor(label, senderLabel) {
  let c = supplierLookup(label);
  if (c !== undefined) return c;
  if (senderLabel) { c = supplierLookup(senderLabel); if (c !== undefined) return c; }
  const k = labelKey(label);
  return (/^WARNER/.test(k) || k === 'NONESUCH' || k === 'PARLOPHONE' || k === 'ROADRUNNER') ? '149' : null;
}
// A per-item label often prints the IMPRINT together with its distributor in brackets
// ("Mute/[PIAS]", "Spinefarm/[PIAS]", "Heavenly Recordings/[PIAS]"). Those are all
// distributed by the sender we already resolved, so the catalog stores the SENDER's
// canonical label and the printed imprint is kept in extra.label_raw. Only fires when the
// bracketed tag really is the sender's own family — it never invents a parent.
function distributedBySender(raw, senderLabel) {
  if (!senderLabel) return false;
  const m = String(raw == null ? '' : raw).match(/\[([^\]]+)\]/);
  if (!m) return false;
  const d = labelKey(m[1]);
  const s = labelKey(senderLabel);
  if (!s || d.length < 3) return false;
  return s.indexOf(d) === 0 || d.indexOf(s) === 0;
}

// Raw label -> canonical, built from the Senders table (label_raw rows) the client
// maintains in Settings. CANONICAL = every canonical output, so an already-canonical
// label is never re-flagged as "unmapped".
const senderRows = $('Senders').all().map(function (i) { return i.json; });
const LABEL_MAP = {};
const CANONICAL = {};
for (const r of senderRows) {
  if (r && r.label) CANONICAL[labelKey(r.label)] = true;
  if (r && r.label_raw && r.label) LABEL_MAP[labelKey(r.label_raw)] = r.label;
}
['NONESUCH', 'ROADRUNNER', 'WARNER', 'PARLOPHONE'].forEach(function (x) { CANONICAL[labelKey(x)] = true; });
// label -> supplier_code, from the same table (prefer a non-blank code when a label appears
// in several rows). Consumed by supplierCodeFor above.
const supplierMap = {};
for (const r of senderRows) {
  if (!r || !r.label) continue;
  const k = labelKey(r.label);
  const c = r.supplier_code != null ? String(r.supplier_code).trim() : '';
  if (!(k in supplierMap) || (c && !supplierMap[k])) supplierMap[k] = c;
}

function keyEan(v) {
  const d = String(v === null || v === undefined ? '' : v).replace(/\D/g, '').replace(/^0+/, '');
  return d || '';
}
function keyCat(v) { return String(v === null || v === undefined ? '' : v).toUpperCase().replace(/[^A-Z0-9]/g, ''); }
function findMatch(pool, used, row) {
  const ean = keyEan(row.ean);
  const cat = keyCat(row.catalogue_no);
  const free = pool.filter(function (c) { return !used.has(c.id); });
  const eanOk = function (c) { const ce = keyEan(c.ean); return !ce || !ean || ce === ean; };
  const tiers = [];
  if (ean) tiers.push(['ean', free.filter(function (c) { return keyEan(c.ean) === ean; })]);
  if (cat) tiers.push(['catalogue_no', free.filter(function (c) { return keyCat(c.catalogue_no) === cat && eanOk(c); })]);
  for (const tier of tiers) {
    if (tier[1].length === 1) return { line: tier[1][0], via: tier[0] };
    if (tier[1].length > 1) return { ambiguous: tier[0], count: tier[1].length };
  }
  return null;
}

function isBlank(v) { return v === null || v === undefined || v === ''; }
function stripBlank(obj) { const out = {}; for (const k of Object.keys(obj)) if (!isBlank(obj[k])) out[k] = obj[k]; return out; }
// The model sometimes emits the STRINGS "null"/"n/a" instead of a real null, so treat
// those (and stray whitespace/dashes) as blank wherever an identifier is judged.
function isBlankish(v) {
  if (v === null || v === undefined) return true;
  const s = String(v).trim();
  return s === '' || /^(null|undefined|n\/?a|-|—)$/i.test(s);
}
function nullIfBlankish(v) { return isBlankish(v) ? null : v; }
function appendNote(existing, add) {
  const cur = String(existing === null || existing === undefined ? '' : existing).trim();
  if (!add) return cur || null;
  if (!cur) return add;
  if (cur.indexOf(add) !== -1) return cur;
  return cur + '\n' + add;
}

// calculation_group: force "1" unless an explicit budget/mid signal is printed.
const MIDBUDGET_RE = /\b(budget|mid[-\s]?price|mid[-\s]?line|nice[-\s]?price|reduced[-\s]?price|low[-\s]?price|super[-\s]?budget)\b/i;
function calcGroup(item, src) {
  const g = String(item.calculation_group == null ? '' : item.calculation_group).trim();
  if (g !== '2' && g !== '3') return '1';
  const text = (item.item_notes || '') + '\n' + ((src && src.body) || '');
  return MIDBUDGET_RE.test(text) ? g : '1';
}

// "We are not sure" must NEVER become an exclusion.
const UNSURE_RE = /\b(UNCLEAR|UNCERTAIN|AMBIGUOUS|POSSIBLY|POTENTIALLY|PRESUMABLY|APPARENTLY|UNKNOWN|UNSPECIFIED|NOT SPECIFIED|NOT CLEAR|CANNOT BE DETERMINED)\b/i;
// Indie exclusivity is NOT a reason to exclude (client, 2026-07): those releases enter
// as in_progress. Only downgrade when "indie" is the ONLY exclusion signal.
const REAL_EXCL_RE = /\b(US|USA|CANADA|AMAZON|D2C|DIGITAL|WEB\s*STORE|EUROPE|EU ONLY|NORTH AMERICA)\b/i;
// Orders never enter the catalog (invoices DO -> Other). The model classifies from
// content; this is a deterministic backup on the SUBJECT only (never bare "order" —
// "pre-order" is a release). Slovenian included.
const ORDER_RE = /\b(purchase\s*order|order\s*(?:no|nr|number|#|confirmation|form)|naro[čc]ilo)\b/i;
// Match common order subjects (EN + Slovenian), but never pre-order/reorder/back-order (a
// pre-order IS a release). This is a backup to the model's document_type below.
function looksLikeOrder(subject) { return ORDER_RE.test(String(subject || '').replace(/\b(?:pre|re|back)-?order/gi, ' ')); }
const DIGITAL_RE = /\b(digital|download|streaming|stream)\b|\bDL\b/i;
const SENTINEL_DATE = '2099-12-31';
// Client date rule: an unannounced date becomes a TBD (stored as the 2099 sentinel, shown as
// "TBD", sent to Hermes as 31.12.2099) ONLY for the Warner group (supplier 149/150); every
// other supplier leaves the date blank in the catalog and blank to Hermes.
function missingDate(supplierCode) { return (supplierCode === '149' || supplierCode === '150') ? SENTINEL_DATE : null; }

// Periodic summary emails (a weekly/monthly planner, a stock list) duplicate releases we
// already receive -> drop them. Deterministic: known sender + a subject keyword.
const PERIODIC = [
  { from: 'david.windmill@warnermusic.com', subject: 'planner' },
  { from: 'danutamorawska@mystic.pl', subject: 'stock' },
];
function isPeriodic(from, subject) {
  const f = String(from || '').toLowerCase();
  const s = String(subject || '').toLowerCase();
  return PERIODIC.some(function (p) { return f.indexOf(p.from) !== -1 && s.indexOf(p.subject) !== -1; });
}

// Senders whose mail NEVER enters the catalog, whatever it contains. "I-DI Offer"
// (orders@i-di.com) blasts promotional OFFER catalogues, not new-release announcements
// (client, 2026-07-30). Matched on the sender NAME or ADDRESS only — never the whole
// i-di.com domain, because I-Di is a real supplier (code 41) whose other addresses do
// send genuine releases.
const BLOCKED_SENDERS = [
  { name: 'i-di offer', email: 'orders@i-di.com' },
];
// The client FORWARDS these in, so the message's own From: is whoever forwarded it and
// the real sender only survives inside the body as a forwarded header
// ("Od: I-DI Offer <orders@i-di.com>" — od = Slovenian "from"). So check the envelope
// AND every forwarded header line. Uses body_full (Chunk Source keeps the whole original
// body on every chunk) so a later chunk can't miss a header that sits at the top.
// The header keywords are shared with the forwarded-block reader below. The body is
// Markdown, so the emphasis Gmail/Outlook forwards carry ("**Od:**", "**Subject**:") has to
// survive the match.
const FWD_FROM_SRC = '^[ \\t>*_-]*(?:od|from|von|de|da|van|fra|από|z)[ \\t*_]*:[ \\t*_]*(.+)$';
const FWD_SUBJECT_SRC = '^[ \\t>*_-]*(?:subject|zadeva|betreff|objet|oggetto|assunto|onderwerp|emne|tema)[ \\t*_]*:[ \\t*_]*(.+)$';
const FWD_FROM_RE = new RegExp(FWD_FROM_SRC, 'gim');
const FWD_FROM_LINE_RE = new RegExp(FWD_FROM_SRC, 'i');
const FWD_SUBJECT_LINE_RE = new RegExp(FWD_SUBJECT_SRC, 'i');
function matchesBlocked(text) {
  const t = String(text || '').toLowerCase();
  if (!t) return false;
  return BLOCKED_SENDERS.some(function (b) {
    return t.indexOf(b.email) !== -1 || t.indexOf(b.name) !== -1;
  });
}
function isBlockedSender(src) {
  if (matchesBlocked(String(src.from || '') + ' ' + String(src.from_name || ''))) return true;
  const body = String(src.body_full || src.body || '');
  FWD_FROM_RE.lastIndex = 0;
  let m;
  while ((m = FWD_FROM_RE.exec(body)) !== null) {
    if (matchesBlocked(m[1])) return true;
  }
  return false;
}

// A forwarded message keeps its own headers in the body. Read them as BLOCKS — a From:
// line together with the Subject: line that follows it inside the same header block — so a
// rule can judge the ORIGINAL sender against the ORIGINAL subject instead of pairing the
// forwarder's envelope address with someone else's subject. No Subject: line in the block
// (some clients drop it) -> fall back to the envelope subject, which then reads "Fwd: ...".
function fwdBlocks(body, fallbackSubject) {
  const lines = String(body || '').split(/\r?\n/);
  const out = [];
  for (let i = 0; i < lines.length; i++) {
    const f = lines[i].match(FWD_FROM_LINE_RE);
    if (!f) continue;
    let subject = null;
    for (let j = i + 1; j < Math.min(i + 8, lines.length); j++) {
      const s = lines[j].match(FWD_SUBJECT_LINE_RE);
      if (s) { subject = s[1]; break; }
    }
    out.push({ from: f[1], subject: subject == null ? fallbackSubject : subject });
  }
  return out;
}

// Internal Nika mail ABOUT STOCK is house-keeping between colleagues (a stock list mailed
// to Mare), not a release announcement, so it never enters the catalog (client,
// 2026-07-30). Deliberately scoped to the stock topic: colleagues also forward genuine
// supplier mail in, so blocking every internal address would swallow those. Like every
// other deterministic net here it reads the SUBJECT only, never the body text.
const INTERNAL_DOMAINS = ['nika.si'];
const STOCK_SUBJECT_RE = /\b(stock|stocks|stocklist|inventory|inventar\w*|zalog\w*)\b/i;
function isInternalAddress(text) {
  const t = String(text || '').toLowerCase();
  return INTERNAL_DOMAINS.some(function (d) {
    const at = '@' + d;
    let i = t.indexOf(at);
    while (i !== -1) {
      const next = t.charAt(i + at.length);
      // "@nika.si.evil.com" / "@nika.sixx" are NOT us.
      if (!next || !/[a-z0-9.-]/.test(next)) return true;
      i = t.indexOf(at, i + 1);
    }
    return false;
  });
}
function isInternalStock(src) {
  // A manual upload is a deliberate human action, never auto-dropped: there the sender IS
  // a nika.si address and the "subject" is the uploaded file name, so this rule would
  // otherwise swallow a file called "stock list.xlsx" without a trace.
  if (String(src.source_kind || '') === 'manual') return false;
  // The message itself has to come from inside Nika. A SUPPLIER's reply quotes our own
  // header block back at us ("From: mare@nika.si / Subject: stock enquiry"), and dropping
  // that reply would lose real releases with no trace — the envelope settles it.
  if (!isInternalAddress(String(src.from || '') + ' ' + String(src.from_name || ''))) return false;
  const subject = String(src.subject || '');
  const blocks = fwdBlocks(src.body_full || src.body, subject);
  // On a forward, judge the ORIGINAL sender: a colleague who forwards a SUPPLIER's stock
  // mail in is internal too, and that mail must still be processed.
  if (blocks.length) return blocks.some(function (b) { return isInternalAddress(b.from) && STOCK_SUBJECT_RE.test(b.subject); });
  return STOCK_SUBJECT_RE.test(subject);
}

// An invoice bills more than the records: it carries FEE / CHARGE lines — Warner's LINEFEE
// "Charge per shipped order line" and UNITFEE "Charge per shipped unit", plus freight,
// handling, pallet and postage lines — and summary/total rows. None of them is a product:
// they have no barcode, cannot be priced, sold or sent to Hermes, and must NEVER become a
// catalog line (client, 2026-07-31).
//
// This is the ENFORCEMENT point and it is deliberately deterministic — no model judgment is
// involved, so the rule cannot regress the way a prompt can. Two independent nets, because
// the single net from v20 (drop only when ean AND title AND artist are all blank) let
// "CHARGE PER SHIPPED UNIT" through on the strength of its title alone:
//   1. isFeeLine below — the line NAMES itself a charge.
//   2. the structural rule in the item loop — no EAN, no catalogue number and no artist
//      identifies no product at all.
// Tripping EITHER one drops the row. Dropping is not silent: raw_entries still stores what
// the model returned, so a rule that ever misfires stays visible and debuggable.
//
// Guards against ever swallowing a real record:
//   - a line carrying an EAN is a real product, always — no fee net can touch it;
//   - the title/format nets only fire on a line with NO artist, and every real release has
//     an artist (a band, a performer, or a glossary marker like OST) while no fee line does.
//     So an album called "Postage" or "Carriage" is safe.
const FEE_CODE_RE = /^(?:LINE|UNIT|ORDER|SERV|SERVICE|FREIGHT|SHIP|SHIPPING|HANDL|HANDLING|ADMIN|PICK|PACK|FUEL|MIN|MINIMUM|CARR|CARRIAGE|POST|POSTAGE|PALLET|DELIV|DELIVERY|TRANSPORT|SURCH|SURCHARGE|INS|INSURANCE|DISC|DISCOUNT|ROUND|ROUNDING|VAT|TAX)?(?:FEE|CHARGE|CHRG|COST)S?$/;
const FEE_TEXT_RE = /\b(?:CHARGE\s+PER\b|SERVICE\s+CHARGE|SERVICE\s+FEE|HANDLING\s+(?:FEE|CHARGE)|FREIGHT(?:\s+(?:FEE|CHARGE|COST))?|SHIPPING\s+(?:FEE|CHARGE|COST)|POSTAGE|CARRIAGE|PALLET\s+(?:FEE|CHARGE)|DELIVERY\s+(?:FEE|CHARGE)|ADMIN(?:ISTRATION)?\s+(?:FEE|CHARGE)|FUEL\s+SURCHARGE|SURCHARGE|MINIMUM\s+ORDER\s+(?:FEE|CHARGE)|PICK(?:ING)?\s+(?:FEE|CHARGE)|PACK(?:ING)?\s+(?:FEE|CHARGE)|ROUNDING|CREDIT\s+NOTE|DELIVERY\s+NOTE|TOTAL\s+QTY|GRAND\s+TOTAL|NET\s+VALUE|SUBTOTAL)\b/;
function isFeeLine(item, title, artist, ean, catNo) {
  if (!isBlankish(ean)) return false; // a barcode means a real product was billed here
  const code = String(catNo == null ? '' : catNo).toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (code && FEE_CODE_RE.test(code)) return true; // LINEFEE, UNITFEE, FREIGHTCHARGE...
  if (!isBlankish(artist)) return false; // has an artist -> a release, not a charge
