    else { cur = cur === null ? l : cur + '\n' + l; } // continuation of the current row
  }
  if (cur !== null) rows.push(cur);
  let products = 0;
  for (const r of rows) if (isProductRow(r)) products++;
  return { head: head, rows: rows, hasSep: hasSep, products: products };
}

// v25: the lines BEFORE the first table — an invoice's header block: the invoice number and
// the supplier's own name and address. Part 1 keeps it because it sits there naturally; every
// later part used to lose it, and with it the only in-document clue to WHO sent the thing. So
// it is repeated at the top of each later part, capped so a long preamble can never crowd out
// the rows, and clearly marked as context so no item is ever extracted from it twice.
// Applied to ATTACHMENTS only: a short email body already rides on every attachment part, and
// a body long enough to split is itself the source of releases — repeating that would invite
// the same release to be extracted twice.
const HEADER_MAX_LINES = 14;
const HEADER_MAX_CHARS = 700;
const HEADER_MARK = '[DOCUMENT HEADER — repeated for context only. It identifies the sender and the document; do NOT extract any item from these lines.]';
function capHeader(lines) {
  const text = lines.join('\n');
  return (text.length > HEADER_MAX_CHARS ? text.slice(0, HEADER_MAX_CHARS) : text).trim();
}
// v26: the preamble belongs to ONE FILE, not to the whole attachment blob. Several files
// are concatenated here, each starting with its own "## Attachment:" heading, and computing
// the preamble once for the blob stamped the FIRST file's letterhead onto later parts of a
// LATER file. Rows from supplier B were then introduced to the model as supplier A's
// invoice — and because that made every chunk agree on the wrong label, the "chunks name
// several labels, so flag instead of guessing" guard in Build Catalog Rows never fired and
// the wrong supplier_code was written silently. A wrong label is worse than a null: a null
// blocks the Hermes send where a human sees it, a wrong code sends cleanly.
// Each table segment now carries the preamble of the file it actually belongs to.
function annotateHeaders(segs) {
  let pending = [];
  let frozen = null;
  for (const s of segs) {
    if (s.type === 'table' && s.tp) {
      if (frozen === null) frozen = capHeader(pending);
      s.hdr = frozen;
      continue;
    }
    for (const l of s.lines) {
      const t = String(l).trim();
      if (HEADING_RE.test(t)) { pending = []; frozen = null; continue; } // a new file starts
      if (frozen !== null || !t) continue;       // past this file's first table, or blank
      if (pending.length < HEADER_MAX_LINES) pending.push(String(l));
    }
  }
}

// Split one Markdown blob (an email body or one attachment) into parts of at most
// MAX_ROWS product rows. Returns { total, confident, prose, parts }.
//   total     = counted product rows across every clean table in the blob.
//   confident = total>0 AND every "|" run we counted looked like a real, separator-
//               delimited table (so `total` can be trusted as an EXACT count).
//   prose     = words of running text outside the tables (may itself list releases).
// A blob that fits in one part is returned whole (only the count is added).
function chunkBlob(text, repeatHeader) {
  const lines = String(text || '').split('\n');
  const segs = [];
  for (const l of lines) {
    const type = isTableLine(l) ? 'table' : 'text';
    if (!segs.length || segs[segs.length - 1].type !== type) segs.push({ type: type, lines: [] });
    segs[segs.length - 1].lines.push(l);
  }

  let total = 0;    // PRODUCT rows only — this is the number asserted to the model
  let rowTotal = 0; // every row, fee rows included — this is what the splitter budgets
  let messyTable = false; // a "|" run we could not parse, or a table with no separator
  let prose = 0;
  for (const s of segs) {
    if (s.type === 'table') {
      s.tp = splitTableSeg(s.lines);
      if (s.tp) { total += s.tp.products; rowTotal += s.tp.rows.length; if (!s.tp.hasSep) messyTable = true; }
      else { messyTable = true; prose += proseWords(s.lines); }
    } else {
      prose += proseWords(s.lines);
    }
  }
  const confident = total > 0 && !messyTable;

  if (rowTotal <= MAX_ROWS) {
    return { total: total, rowTotal: rowTotal, confident: confident, prose: prose, parts: [{ text: String(text || ''), rows: rowTotal, products: total }] };
  }

  // Long enough to split. Repeat the "## Attachment:" heading and the table head in
  // every part; prose stays with the part it appears in (repeating it would invite
  // the same release to be extracted twice).
  const parts = [];
  let heading = '';
  if (repeatHeader) annotateHeaders(segs);
  let cur = [];
  let curRows = 0;
  let curProducts = 0;
  for (const s of segs) {
    if (s.type === 'text' || !s.tp) {
      for (const l of s.lines) { if (HEADING_RE.test(String(l).trim())) heading = String(l).trim(); cur.push(l); }
      continue;
    }
    const header = repeatHeader ? (s.hdr || '') : '';
    for (const l of s.tp.head) cur.push(l);
    for (const row of s.tp.rows) {
      if (curRows >= MAX_ROWS) {
        parts.push({ text: cur.join('\n').trim(), rows: curRows, products: curProducts });
        cur = [];
        curRows = 0;
        curProducts = 0;
        if (heading) { cur.push(heading); cur.push(''); }
        if (header) { cur.push(HEADER_MARK); cur.push(header); cur.push(''); }
        for (const l of s.tp.head) cur.push(l);
      }
      cur.push(row);
      curRows++;
      if (isProductRow(row)) curProducts++;
    }
  }
  if (curRows) parts.push({ text: cur.join('\n').trim(), rows: curRows, products: curProducts });
  else if (cur.join('').trim() && parts.length) parts[parts.length - 1].text += '\n' + cur.join('\n').trim();
  return { total: total, rowTotal: rowTotal, confident: confident, prose: prose, parts: parts };
}

// Build the instruction that governs how many items a part must yield.
//   rows       = counted product rows in THIS part (0 when nothing tabular counted).
//   exact      = those rows came from a clean, separator-delimited table, so `rows`
//                is trustworthy as a hard target.
//   proseSource= this part ALSO carries running text that is part of the source (not
//                already-extracted context) and may itself list releases.
// When both a trustworthy table count AND prose are present, the count is asserted as
// a FLOOR for the table plus "extract every release in the text too" — never a hard
// total that could make the model drop a prose-only release. When the count is not
// trustworthy, no number is asserted at all (a wrong number is worse than none); the
// barcode audit in Build Raw Entry1 is the backstop.
function note(index, count, rows, exact, proseSource, bodyIsSource) {
  let core;
  if (rows > 0 && exact && !proseSource) {
    core = 'This part contains exactly ' + rows + ' product rows: return EXACTLY that many items, one per row, in the same order. Never sample, summarise, shorten or stop early — a row you skip is a release the client never gets to sell.';
  } else if (rows > 0 && exact && proseSource) {
    core = 'The table in this part has exactly ' + rows + ' product rows: return an item for EVERY one, one per row, none skipped. The message text above is ALSO part of this source — extract every release it lists in addition (there may be none). Never sample, summarise or stop early.';
  } else {
    core = 'Extract every single release this part contains — one item each, reading top to bottom. Never sample, summarise, shorten or stop early; a release you skip is one the client never gets to sell.';
  }
  if (count === 1) return core;
  return 'PART ' + index + ' OF ' + count + ' of this source. ' + core +
    (bodyIsSource ? '' : ' The message text above is CONTEXT ONLY in this part — the items it lists were already extracted in an earlier part, so do not repeat them here.');
}

function chunkSource(inputs) {
  const out = [];
  for (let i = 0; i < inputs.length; i++) {
    const src = inputs[i].json;
    const body = src.body || '';
    const att = src.attachments_text || '';
    const B = chunkBlob(body, false);
    const A = chunkBlob(att, true);
    const total = B.total + A.total;          // product rows -> the count the model is given
    const rowTotal = B.rowTotal + A.rowTotal;  // all rows -> the size the splitter works on

    const base = Object.assign({}, src, { body_full: body, attachments_full: att });

    // Whole source fits in one AI call. Assert an exact count only when the tables are
    // clean AND there is no substantial prose that might carry its own releases.
    if (rowTotal <= MAX_ROWS) {
      const cleanTables = (A.total === 0 || A.confident) && (B.total === 0 || B.confident);
      const proseSource = (A.prose + B.prose) > 40; // running text beyond the table(s)
      const exact = total > 0 && cleanTables;
      out.push({
        json: Object.assign({}, base, {
          chunk_index: 1, chunk_count: 1, chunk_rows: total,
          chunk_note: note(1, 1, total, exact, proseSource, true),
        }),
        pairedItem: { item: i },
      });
      continue;
    }

    // Long source. Which carrier is long decides the shape (mirrors v12): a short body
    // rides on every attachment part as context; a body long enough to split becomes
    // parts of its own and the attachment parts that follow drop it.
    const used = function (p) { return p.rows > 0 || p.text.trim() !== ''; };
    const bParts = B.parts.filter(used);
    const aParts = A.parts.filter(used);
    const bodyIsProse = B.total === 0 && B.prose > 0; // body carries releases only as text
    const bodyProseSource = bodyIsProse && B.prose > 40;

    const parts = [];
    if (B.rowTotal > MAX_ROWS) {
      for (const p of bParts) parts.push({ body: p.text, att: '', rows: p.products, exact: B.confident, proseSource: B.prose > 40, bodySource: true });
      for (const p of aParts) parts.push({ body: '', att: p.text, rows: p.products, exact: A.confident, proseSource: false, bodySource: false });
    } else if (aParts.length) {
      for (let k = 0; k < aParts.length; k++) {
        const first = k === 0;
        parts.push({
          body: body,
          att: aParts[k].text,
          rows: aParts[k].products + (first ? B.total : 0),
          exact: A.confident && (!first || B.total === 0 || B.confident),
          proseSource: first && bodyProseSource,
          bodySource: first,
        });
      }
    } else {
      for (const p of bParts) parts.push({ body: p.text, att: att, rows: p.products, exact: B.confident, proseSource: B.prose > 40, bodySource: true });
    }

    for (let k = 0; k < parts.length; k++) {
      const P = parts[k];
      out.push({
        json: Object.assign({}, base, {
          body: P.body,
          attachments_text: P.att,
          chunk_index: k + 1,
          chunk_count: parts.length,
          chunk_rows: P.rows,
          chunk_note: note(k + 1, parts.length, P.rows, P.exact, P.proseSource, P.bodySource),
        }),
        pairedItem: { item: i },
      });
    }
  }
  return out;
}

const inputs = $input.all();
return chunkSource(inputs);
